package com.example.rokidgeminisecretary;
import android.Manifest;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.CancellationSignal;import android.provider.CalendarContract;import org.json.*;import java.util.*;
/** On-demand local calendar reads. Never writes events or persists their locations. */
final class CalendarNavigation {
 static final class Ticket {final JSONObject event;final int day;final long elapsed=android.os.SystemClock.elapsedRealtime();Ticket(JSONObject e,int d)throws Exception{event=new JSONObject(e.toString());day=d;}}
 private static final LinkedHashMap<String,Ticket> tickets=new LinkedHashMap<>();
 static synchronized String ticket(JSONObject event,int day)throws Exception{while(tickets.size()>=256)tickets.remove(tickets.keySet().iterator().next());String id=UUID.randomUUID().toString();tickets.put(id,new Ticket(event,day));return id;}
 static boolean same(JSONObject a,JSONObject b){return a.optLong("event",-1)==b.optLong("event",-2)&&a.optLong("begin")==b.optLong("begin")&&a.optLong("end")==b.optLong("end")&&a.optString("location").equals(b.optString("location"))&&a.optString("title").equals(b.optString("title"))&&a.optBoolean("available")==b.optBoolean("available")&&a.optBoolean("allDay")==b.optBoolean("allDay");}
 static JSONObject resolve(Context c,String token)throws Exception {Ticket t;synchronized(CalendarNavigation.class){t=tickets.get(token);}if(t==null||android.os.SystemClock.elapsedRealtime()-t.elapsed>TTL)return changed();CancellationSignal cancel=new CancellationSignal();android.os.Handler h=new android.os.Handler(android.os.Looper.getMainLooper());Runnable stop=()->cancel.cancel();h.postDelayed(stop,10000);try{JSONObject state=read(c,t.day,cancel);JSONArray rows=state.optJSONArray("items");for(int i=0;rows!=null&&i<rows.length();i++){JSONObject e=rows.optJSONObject(i);if(e.optBoolean("available")&&same(t.event,e)){e.remove("event");return new JSONObject().put("ok",true).put("status","selected").put("item",e);}}return changed();}catch(Exception unavailable){return changed();}finally{h.removeCallbacks(stop);}}
 static JSONObject changed()throws Exception{return new JSONObject().put("ok",true).put("status","changed").put("message","予定が変更・終了したか、読み取りできません。予定を選び直してください").put("items",new JSONArray());}
 static final int LIMIT=60; static final long TTL=300000L;
 static final class Window {final long from,to;Window(long f,long t){from=f;to=t;}}
 static Window window(int day,long now,TimeZone zone){if(day<0||day>1)throw new IllegalArgumentException("日付を選び直してください");Calendar c=Calendar.getInstance(zone);c.setTimeInMillis(now);c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);c.add(Calendar.DATE,day);long f=c.getTimeInMillis();c.add(Calendar.DATE,1);return new Window(f,c.getTimeInMillis());}
 static boolean inDay(long start,long end,boolean all,Window w,TimeZone zone){if(end<=start)return false;if(!all)return start<w.to&&end>w.from;java.text.SimpleDateFormat utc=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.ROOT),local=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.ROOT);utc.setTimeZone(TimeZone.getTimeZone("UTC"));local.setTimeZone(zone);return utc.format(new Date(start)).compareTo(local.format(new Date(w.to)))<0&&utc.format(new Date(end)).compareTo(local.format(new Date(w.from)))>0;}
 static String reason(String location){String s=location==null?"":location.trim();if(s.isEmpty())return "場所が未登録";if(s.length()>200)return "場所が長すぎます。スマホで目的地を入力してください";if(s.matches("(?is).*(https?://|www\\.).*")||s.matches("(?is).*(オンライン|リモート|zoom|google meet|teams会議).*"))return "オンライン・リンクの場所です。目的地を確認してください";return "";}
 static JSONObject row(long id,long begin,long end,boolean all,String title,String location)throws Exception {String loc=location==null?"":location.trim();String why=reason(loc);return new JSONObject().put("event",id).put("begin",begin).put("end",end).put("allDay",all).put("title",title==null||title.trim().isEmpty()?"名称なしの予定":title.substring(0,Math.min(80,title.length()))).put("location",loc.length()>200?"":loc).put("available",why.isEmpty()).put("reason",why);}
 static String label(JSONObject e){java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("M/d HH:mm",Locale.JAPAN);return (e.optBoolean("allDay")?"終日":f.format(new Date(e.optLong("begin"))))+" "+e.optString("title")+"\n"+(e.optBoolean("available")?e.optString("location"):e.optString("reason"));}
 interface Query {Cursor run(Uri uri,String[] projection,String selection,String[] args,String sort,CancellationSignal signal);}
 static JSONObject read(Context c,int day,CancellationSignal cancel)throws Exception {
  if(c.checkSelfPermission(Manifest.permission.READ_CALENDAR)!=0)return new JSONObject().put("ok",true).put("status","permission_required").put("message","スマホのNAVI → 予定から目的地で、カレンダーの読み取りを許可してください").put("items",new JSONArray());
  return readData((uri,projection,selection,args,sort,signal)->c.getContentResolver().query(uri,projection,selection,args,sort,signal),day,System.currentTimeMillis(),TimeZone.getDefault(),cancel);
 }
 static JSONObject readData(Query query,int day,long now,TimeZone zone,CancellationSignal cancel)throws Exception {
  cancel.throwIfCanceled();Window w=window(day,now,zone);ArrayList<String> ids=new ArrayList<>();
  try(Cursor cs=query.run(CalendarContract.Calendars.CONTENT_URI,new String[]{"_id"},"account_type=? AND visible=1 AND sync_events=1",new String[]{"com.google"},null,cancel)){if(cs==null)throw new IllegalStateException();while(cs.moveToNext())ids.add(cs.getString(0));}
  JSONArray rows=new JSONArray();boolean truncated=false;
  if(!ids.isEmpty()){StringBuilder marks=new StringBuilder();for(String id:ids){if(marks.length()>0)marks.append(',');marks.append('?');}Uri.Builder b=CalendarContract.Instances.CONTENT_URI.buildUpon();ContentUris.appendId(b,w.from-86400000L);ContentUris.appendId(b,w.to+86400000L);String selection="calendar_id IN ("+marks+") AND deleted=0 AND (eventStatus IS NULL OR eventStatus!=2) AND (selfAttendeeStatus IS NULL OR selfAttendeeStatus!=2)";
   try(Cursor cs=query.run(b.build(),new String[]{"event_id","begin","end","allDay","title","eventLocation"},selection,ids.toArray(new String[0]),"begin ASC",cancel)){if(cs==null)throw new IllegalStateException();while(cs.moveToNext()){cancel.throwIfCanceled();long begin=cs.getLong(1),end=cs.getLong(2);boolean all=cs.getInt(3)!=0;if(!inDay(begin,end,all,w,zone)||(!all&&end<=now))continue;if(rows.length()==LIMIT){truncated=true;break;}rows.put(row(cs.getLong(0),begin,end,all,cs.getString(4),cs.getString(5)));}}
  }
  return new JSONObject().put("ok",true).put("status",ids.isEmpty()?"no_calendar":rows.length()==0?"empty":"ready").put("message",ids.isEmpty()?"同期済みのGoogleカレンダーがありません。スマホのアカウント・同期設定を確認してください":rows.length()==0?"この日の未終了の予定はありません":"場所を確認して選んでください。検索は今から出発する条件です").put("day",day).put("readAt",now).put("truncated",truncated).put("items",rows);
 }
 static JSONObject response(Context c,int day)throws Exception{CancellationSignal cancel=new CancellationSignal();android.os.Handler h=new android.os.Handler(android.os.Looper.getMainLooper());Runnable stop=()->cancel.cancel();h.postDelayed(stop,10000);try{JSONObject out=read(c,day,cancel);JSONArray items=out.getJSONArray("items");for(int i=0;i<items.length();i++){JSONObject e=items.getJSONObject(i);e.put("label",label(e));e.put("token",ticket(e,day));e.remove("event");}return out;}catch(Exception error){return new JSONObject().put("ok",true).put("status","unavailable").put("message","予定を取得できません。スマホの権限・同期を確認して選び直してください").put("items",new JSONArray());}finally{h.removeCallbacks(stop);}}
 static boolean fresh(JSONObject response,long now){long age=now-response.optLong("readAt",0);return response.optString("status").equals("ready")&&age>=0&&age<=TTL;}
 private CalendarNavigation(){}
}
